#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

/* The function executed by the new thread */
void *worker_routine(void *arg) {
    int *data = (int *)arg;
    printf("Worker Thread: Received data value %d\n", *data);
    sleep(1); /* Simulate work */
    return (void*)0;
}

int main() {
    pthread_t thread_id;
    int shared_data = 100;
    int result;

    /* Create the new thread */
    result = pthread_create(&thread_id, NULL, worker_routine, &shared_data);

    if (result != 0) {
        fprintf(stderr, "Error creating thread: %d\n", result);
        return 1;
    }

    printf("Main Thread: Created thread with ID %lu. Waiting for join...\n", (unsigned long)thread_id);

    /* Wait for the worker thread to finish */
    result = pthread_join(thread_id, NULL);

    if (result != 0) {
        fprintf(stderr, "Error joining thread: %d\n", result);
        return 1;
    }

    printf("Main Thread: Worker thread finished successfully.\n");

    return 0;
}
